302:   private async startRequest(request: EvalRun['request'], pinnedPrompts?: EvalRunPrompt[]) {
303:     await this.ready;
304:     const hash = sha256(JSON.stringify(request));
305:     let pending = this.starts.get(request.requestId);
306:     if (!pending) {
307:       pending = (async () => (await this.store.read(request.requestId)) ?? this.prepare(request, hash, pinnedPrompts))();
308:       this.starts.set(request.requestId, pending);
309:     }
310:     try {
311:       const run = await pending;
312:       if (run.deletedAt) throw new ApplicationError('conflict', 'This run was deleted. Use a new request ID.');
313:       if (run.requestHash !== hash) throw new ApplicationError('conflict', 'Request ID already used for another run.');
314:       return summarizeEvalRun(run);
315:     } finally { if (this.starts.get(request.requestId) === pending) this.starts.delete(request.requestId); }
316:   }
