584:         const generated = await this.generateValidated({ ...common, stage: 'linked', body: prompt.stages.linked,
585:           schema: linkedCanvasesOutputSchema, files: {
586:             'context.json': { name: saved.name, description: saved.description, snapshot: saved.resolvedSnapshot ?? saved.snapshot },
587:             'canvases.json': canvasInputs.map((copy, i) => {
588:               const document = documentFromHistory(copy.history), context = canvasContext(copy, false);
589:               return { id: `c${i + 1}`, ...context, jumps: [
590:                 ...(document.jumps ?? []), ...context.diagrams.flatMap(d => {
591:                   const box = connectionBox(document.scene, d.id);
592:                   return box?.kind === 'diagram' ? (document.scene.contents[box.contentId].jumps ?? []).map(jump => ({ ...jump, sourceDisplayNodeId: d.id })) : [];
593:                 })
594:               ] };
595:             })
596:           } }, raw => materializeLinkedCanvases(raw, canvasInputs, `linked-${sha256(run.id + ':' + cell.key).slice(0, 16)}`));
