267:       : target.kind === 'judgements' ? go({ kind: 'judgements', id: target.id, judgementId: target.judgementId })
268:       : target.kind === 'canvas' || target.kind === 'session' ? go({ kind: target.kind, id: target.id }) : undefined,
269:     deleteRun: item => {
270:       const family = [item, ...(runs ?? []).filter(other => other.parentRunId === item.id)];
271:       const outputs = family.reduce((sum, member) => sum + member.cells.filter(hasEvalOutput).length, 0);
272:       void remove(`Delete run #${numbers.get(item.id)}${family.length > 1 ? `, its ${family.length - 1} rerun${family.length > 2 ? 's' : ''}` : ''} and ${outputs} outputs?`,
273:         () => deleteRun(item.id), current => current.kind === 'run' && family.some(member => member.id === current.id));
274:     },
275:     deleteCanvas: (id, name) => void remove(`Delete output “${name}”?`, () => deleteGenerated(id),
276:       current => current.kind === 'canvas' && current.id === id || current.kind === 'run' && current.id === run?.id && shownCell?.canvasId === id,
277:       () => { updateGenerated(items => items?.filter(item => item.id !== id));
278:         updateRuns(items => items?.map(item => ({ ...item, cells: item.cells.map(cell => cell.canvasId === id ? { ...cell, deleted: true } : cell) })));
279:         setPicked(items => items.filter(item => item.canvasId !== id)); }),
280:     deleteContext: context => void remove(`Delete all ${context.outputs} outputs, runs and comparisons generated from “${context.name}” (${context.workflow === 'roll-up' ? 'roll-ups' : 'alternatives'})? The AgentContext itself is kept.`,
281:       () => deleteContextOutputs(context.id, context.workflow), current => current.kind === 'run' ? runs?.some(item => item.id === current.id && item.agentContextId === context.id && item.workflow === context.workflow) === true
282:         : current.kind === 'canvas' ? generated?.some(item => item.id === current.id && item.generated?.agentContextId === context.id && generatedWorkflow(item.generated) === context.workflow) === true
283:         : current.kind === 'session' && sessions?.some(item => item.id === current.id && !item.mixedOrigins && item.origins.length > 0 && item.origins.every(origin => origin.agentContextId === context.id && origin.workflow === context.workflow)) === true),
284:     runMenu: (item, at) => setMenu({ label: `Run #${numbers.get(item.id)}`, at, sections: [{ label: `Run #${numbers.get(item.id)} · ${item.contextName}`, items: [
285:       // Opens the exact version the run pinned; prompts deleted or unknown (legacy runs) are skipped.
286:       ...item.prompts.filter(pinned => prompts?.some(prompt => prompt.id === pinned.promptId)).map(pinned => ({
287:         label: item.prompts.length > 1 ? `Edit prompt “${pinned.name}”` : 'Edit prompt', detail: `v${pinned.version}`,
288:         onSelect: () => go({ kind: 'prompt', id: pinned.promptId, version: pinned.version }) })),
289:       ...(item.compatibility ? [{ label: 'Rerun with original chat settings', onSelect: () => void rerunChat(item.id, crypto.randomUUID()).then(started).catch(onError) }] : [{ label: 'Rerun…', onSelect: () => setLaunch({ workflow: item.workflow, rerun: item }) }]),
290:       ...(item.legacy ? [] : [{ label: 'Rename', onSelect: () => setRenaming(item.id) }]),
291:       ...(runActive(item) && !item.legacy ? [{ label: 'Cancel run', onSelect: () => void cancelRun(item.id).then(() => refreshRuns()).catch(onError) }] : []),
292:       { label: 'Delete run…', danger: true, onSelect: () => treeActions.deleteRun(item) }
293:     ] }] }),
294:     renameRun: (item, name) => void renameRun(item.id, name).then(() => refreshRuns()).catch(onError),
295:     contextMenu: (context, at) => setMenu({ label: context.name, at, sections: [{ label: context.name, items: [
296:       { label: 'New run from this context…', onSelect: () => {
297:         if (context.workflow !== 'roll-up') { setLaunch({ workflow: context.workflow, contextId: context.id }); return; }
298:         // Roll-ups reuse the latest run's child and parent canvases.
299:         const latest = context.runs[0];
300:         setLaunch({ workflow: 'roll-up', ...(latest ? { rerun: latest } : {}) });
301:       } },
302:       { label: 'Delete outputs…', danger: true, onSelect: () => treeActions.deleteContext({ id: context.id, name: context.name, workflow: context.workflow,
303:         outputs: context.outputs }) }
304:     ] }] }),
305:   };
306:   const openDiagram = (leaf: DiagramLeaf) => go({ kind: 'new-reference', target: { source: leaf.source, diagramId: leaf.diagram.diagramId } });
307:   const openReference = (id: string) => go({ kind: 'reference', id });
308:   const archiveReference = (reference: EvalReference) => void updateReference(reference.id, { archived: true }).then(referenceChanged).catch(onError);
309:   const moveReference = (reference: EvalReference, groupId: string | null) => void updateReference(reference.id, { groupId }).then(referenceChanged).catch(onError);
310:   const createGroup = (name: string) => void createReferenceGroup({ requestId: crypto.randomUUID(), name }).then(groupChanged).catch(onError);
311:   const renameGroup = (group: EvalReferenceGroup, name: string) => void renameReferenceGroup(group.id, name).then(groupChanged).catch(onError);
312:   const deleteGroup = (group: EvalReferenceGroup, members: number) => setConfirmation({ title: 'Delete group', confirmLabel: 'Delete group',
313:     message: `Delete group “${group.name}”?${members ? ` Its ${members} reference${members === 1 ? '' : 's'} stay and become ungrouped.` : ''}`, onConfirm: async () => {
314:       await deleteReferenceGroup(group.id);
315:       setReferenceGroups(current => current.filter(item => item.id !== group.id));
316:       await refreshReferences();
317:     } });
318:   const promptsMenu = (at: { x: number; y: number }) => setMenu({ label: 'Prompts', at, sections: evalWorkflowIds.map(id => ({ label: evalWorkflows[id].label, items: [
319:     ...(prompts ?? []).filter(prompt => prompt.workflow === id).map(prompt => ({ label: prompt.name, detail: `v${latestVersion(prompt).version}${prompt.archivedAt ? ' · archived' : ''}`,
320:       muted: !!prompt.archivedAt, onSelect: () => go({ kind: 'prompt', id: prompt.id }) })),
321:     { label: `+ New ${evalWorkflows[id].label.toLowerCase()} prompt`, onSelect: () => go({ kind: 'new-prompt', workflow: id }) }
322:   ] })) });
323:   const canvas = route.kind === 'canvas' ? generated?.find(item => item.id === route.id) : undefined;
324: 
325:   const content = () => {
326:     if (route.kind === 'prompt' && current && route.version && !current.versions.some(version => version.version === route.version))
327:       return <p className="evals-message">Prompt v{route.version} is not available in the current catalog. Its captured text remains in the run details.</p>;
328:     if (route.kind === 'reference') {
329:       const reference = references?.find(item => item.id === route.id);
330:       return reference ? <ReferenceView key={reference.id} reference={reference} groups={referenceGroups} prompts={prompts ?? []} onChanged={referenceChanged} onOpenPrompt={id => go({ kind: 'prompt', id })} />
331:         : references && <p className="evals-message">Reference not found.</p>;
332:     }
333:     if (route.kind === 'experiment') return !experiments || !runs || !judgements ? <p role="status">Loading experiment…</p> : activeExperiment ? <ExperimentView key={`${activeExperiment.id}:${route.view}:${route.groupId}:${route.phaseId}`} experiment={activeExperiment} onChanged={refreshAll} prompts={prompts ?? []} route={route} runs={runs ?? []} judgements={judgements ?? []} onOpen={go} picked={picked} onPick={(output, on) => setPicked(current => on ? [...current.filter(p => p.canvasId !== output.canvasId), output] : current.filter(p => p.canvasId !== output.canvasId))} /> : <p>Experiment not found.</p>;
334:     if (route.kind === 'references') return <ReferencesLanding count={activeReferences.length} onCapture={() => go({ kind: 'new-reference', target: lastDiagram.current })} />;
335:     if (route.kind === 'new-reference') return <ReferenceWorkbench target={route.target} candidates={candidates} groups={referenceGroups} captures={captures} setCaptures={setCaptures}
336:       onCreated={referenceChanged} onGroupCreated={groupChanged} onOpenReference={id => go({ kind: 'reference', id })} />;
337:     if (route.kind === 'prompt') return current ? <PromptEditor references={references} key={`${current.id}:${latestVersion(current).version}:${route.version ?? ''}`} prompt={current} version={route.version} onSaved={savedPrompt} onDirty={setDirty}
338:       onRun={prompt => setLaunch({ workflow: prompt.workflow, promptIds: [prompt.id] })} onDuplicate={(prompt, version) => go({ kind: 'new-prompt', workflow: prompt.workflow, from: prompt.id, fromVersion: version })} />
339:       : prompts && <p className="evals-message">Prompt not found.</p>;
340:     if (route.kind === 'new-prompt') {
341:       const from = route.from ? prompts?.find(prompt => prompt.id === route.from) : undefined;
342:       if (route.from && !prompts) return null;
343:       return <PromptEditor references={references} key={`new:${route.workflow}:${route.from ?? ''}:${route.fromVersion ?? ''}`} draft={{ workflow: route.workflow, from, fromVersion: route.fromVersion }} onSaved={savedPrompt} onDirty={setDirty}
344:         onRun={() => {}} onDuplicate={() => {}} />;
345:     }
346:     if (route.kind === 'canvas') return generated && (canvas ? <div className="output-view"><CanvasPreview key={canvas.id} canvasId={canvas.id} bare /></div>
347:       : <p className="evals-message">This output was deleted.</p>);
348:     if (route.kind === 'run') {
349:       if (!runs) return null;
350:       if (!run) return <p className="evals-message">Run not found.</p>;
351:       return shownCell ? <>
352:         {outputIndex >= 0 && <nav className="output-navigation" aria-label="Output navigation">
353:           <button aria-keyshortcuts="ArrowLeft" disabled={outputIndex === 0} onClick={() => moveOutput(-1)}>← Previous output</button>
354:           <span title={outputItems[outputIndex].label} aria-live="polite">{outputIndex + 1} / {outputItems.length} · {outputItems[outputIndex].label}</span>
355:           <button aria-keyshortcuts="ArrowRight" disabled={outputIndex === outputItems.length - 1} onClick={() => moveOutput(1)}>Next output →</button>
356:         </nav>}
357:         <OutputView key={`${run.id}:${shownCell.key}`} cell={shownCell} run={run} />
358:       </> : <p className="evals-message">This run has no outputs.</p>;
359:     }
360:     if (route.kind === 'judgements') return <JudgementsPane items={judgementItems}
361:       selectedId={route.judgementId} initialEntry={route.entry} prompts={prompts ?? []} onSelect={(judgementId, entry) => go({ kind: 'judgements', judgementId, entry })}
362:       onDelete={item => remove(`Delete judgement “${item.title}”?${item.runIds.length > 1 ? ' This removes it from every attached run.' : ''}`, () => deleteJudgement(item.id), () => false)} />;
363:     if (route.kind === 'session') return session ? <ComparisonView key={session.id} session={session} prompts={prompts ?? []} />
364:       : !error && <p role="status" className="evals-message">Loading comparison…</p>;
365:     return home();
366:   };
