368:   function home() {
369:     return <div className="evals-home">
370:       {!!experiments?.length && <section aria-label="Experiments"><h2>Experiments</h2><div className="evals-home-cards">{experiments.map(e => <section className="evals-card" key={e.id}><h3><button className="evals-link" onClick={() => go({ kind: 'experiment', id: e.id })}>{e.name}</button></h3><p>{e.description}</p><p>{e.conditions.length} conditions · {e.cases.length} input cases · {experimentJudgementIds(e).length} Judgements</p></section>)}</div></section>}
371:       <h2>Generate, then compare</h2>
372:       <p className="evals-muted">Write prompt versions for a workflow, run several at once against the same inputs, and compare their outputs side by side.</p>
373:       <div className="evals-home-cards">
374:         {evalWorkflowIds.map(id => { const workflow = evalWorkflows[id], count = prompts?.filter(prompt => prompt.workflow === id && !prompt.archivedAt).length ?? 0;
375:           return <section key={id} className="evals-card" aria-label={`${workflow.label} workflow`}>
376:             <h3>{workflow.label}</h3><p>{workflow.description}</p>
377:             <p className="evals-muted">{count} prompt{count === 1 ? '' : 's'} · {workflow.stages.map(stage => stage.id).join(' → ')}</p>
378:             <div className="evals-actions"><button type="button" onClick={() => go({ kind: 'new-prompt', workflow: id })}>New prompt</button>
379:               <button type="button" className="is-primary" onClick={() => setLaunch({ workflow: id })}>New run…</button></div>
380:           </section>; })}
381:       </div>
382:       {!!runs?.length && <section aria-label="Recent runs"><h3>Recent runs</h3><ul className="evals-recent">{runs.slice(0, 5).map(item => <li key={item.id}>
383:         <button type="button" className="evals-link" onClick={() => go({ kind: 'run', id: item.id })}>{runTitle(item, numbers.get(item.id))}</button>
384:         <span className="evals-status" data-status={item.status}>{statusLabel[item.status]}</span><span className="evals-muted">{runProgress(item)} · {relativeTime(item.createdAt)}</span>
385:       </li>)}</ul></section>}
386:     </div>;
387:   }
388: 
389:   return <main className="evals-page">
390:     <header className="evals-header">
391:       <a href={import.meta.env.BASE_URL}>← Mapping</a>
392:       <h1><button type="button" className="evals-home-link" onClick={() => go({ kind: 'home' })}>Evals</button></h1>
393:       <span className="evals-muted">Prompt workflows, runs and comparisons</span>
394:       <span className="evals-spacer" />
395:       <button type="button" aria-current={inReferences ? 'page' : undefined} className={inReferences ? 'is-active' : undefined} onClick={() => go({ kind: 'references' })}>References</button>
396:       <button type="button" aria-haspopup="menu" onClick={event => { const box = event.currentTarget.getBoundingClientRect(); promptsMenu({ x: box.left, y: box.bottom + 4 }); }}>Prompts ▾</button>
397:       <button type="button" className="evals-header-secondary" onClick={() => setTemplatesOpen(true)}>Layout templates</button>
398:       <button type="button" className="evals-header-secondary" onClick={() => setLaunch('compare')}>New comparison</button>
399:       <details className="evals-header-more"><summary>More</summary><div>
400:         <button type="button" onClick={() => setTemplatesOpen(true)}>Layout templates</button>
401:         <button type="button" onClick={() => setLaunch('compare')}>New comparison</button>
402:       </div></details>
403:       {!activeExperiment && <button type="button" className="is-primary" onClick={() => setLaunch({ workflow: route.kind === 'prompt' && current ? current.workflow : 'roll-up' })}>New run</button>}
404:     </header>
405:     <div className="evals-layout" ref={layout} style={{ gridTemplateColumns: `${navWidth}px 5px minmax(0, 1fr)` }}>
406:       <nav className="evals-nav" aria-label="Evals">
407:         {inReferences ? (references ? <ReferenceExplorer tab={route.kind === 'new-reference' ? 'canvas' : 'references'} references={activeReferences} groups={referenceGroups}
408:             current={route.kind === 'reference' ? route.id : undefined} captureCount={captures.length} candidates={candidates} candidatesError={candidatesError}
409:             currentDiagramKey={route.kind === 'new-reference' && route.target ? diagramLeafKey(route.target.source, route.target.diagramId) : undefined}
410:             onTab={tab => go(tab === 'canvas' ? { kind: 'new-reference', target: lastDiagram.current } : { kind: 'references' })} onExit={() => go({ kind: 'home' })}
411:             onOpenDiagram={openDiagram} onOpen={openReference} onMenu={setMenu} onArchive={archiveReference} onMove={moveReference}
412:             onCreateGroup={createGroup} onRenameGroup={renameGroup} onDeleteGroup={deleteGroup} />
413:           : <p role="status" className="evals-muted">Loading…</p>)
414:         : runs && generated && sessions && experiments && judgements ? <>
415:           <ExperimentExplorer experiments={experiments} runs={runs} judgements={judgements ?? []} selection={selection} onOpen={treeActions.open} />
416:           <details className="experiment-legacy" open={experiments.length ? undefined : true}><summary>Run history <small>{legacyRuns.length}</small></summary>
417:           <EvalsTree runs={legacyRuns} generated={generated.filter(c => !registeredCanvases.has(c.id))} judgements={(judgements ?? []).filter(j => !registeredReports.has(j.id))} selection={selection} actions={treeActions} renaming={renaming} onRenameEnd={() => setRenaming(undefined)}
418:             picked={picked} onPick={(output, on) => setPicked(current => on ? [...current.filter(item => item.canvasId !== output.canvasId), output] : current.filter(item => item.canvasId !== output.canvasId))} />
419:           </details></>
420:           : <p role="status" className="evals-muted">Loading…</p>}
421:         {picked.length > 0 && runs && <CompareBar picked={picked} runs={runs} onClear={() => setPicked([])} onSession={openSession} onComparisonStarted={comparisonStarted} />}
422:       </nav>
423:       <div role="separator" aria-label="Resize sidebar" aria-orientation="vertical" aria-valuemin={200} aria-valuemax={560} aria-valuenow={navWidth} tabIndex={0}
424:         className="evals-divider evals-nav-divider" onDoubleClick={() => resize(300)}
425:         onKeyDown={event => { if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') { event.preventDefault(); resize(navWidth + (event.key === 'ArrowLeft' ? -16 : 16)); } if (event.key === 'Home') resize(300); }}
426:         onPointerDown={event => { if (event.button === 0) { event.preventDefault(); event.currentTarget.setPointerCapture(event.pointerId); } }}
427:         onPointerMove={event => { if (event.currentTarget.hasPointerCapture(event.pointerId)) resize(event.clientX - layout.current!.getBoundingClientRect().left); }}
428:         onPointerUp={event => { if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId); }} />
429:       <section className="evals-content">
430:         {error && <p role="alert" className="evals-error">{error} <button type="button" className="evals-link" onClick={() => setError('')}>Dismiss</button></p>}
431:         {activeExperiment && route.kind !== 'experiment' && <div className="experiment-breadcrumb"><button className="evals-link" onClick={() => go({ kind: 'experiment', id: activeExperiment.id })}>{activeExperiment.name}</button><span>› {route.kind === 'judgements' ? 'Judgement' : 'Stage output'}</span><button className="evals-link" onClick={() => go({ kind: 'experiment', id: activeExperiment.id, view: 'outputs' })}>All outputs</button></div>}
432:         {loading && route.kind === 'home' ? <p role="status" className="evals-message">Loading…</p> : content()}
433:       </section>
434:     </div>
435:     {confirmation && <ConfirmDialog {...confirmation} onClose={() => setConfirmation(undefined)} />}
436:     {templatesOpen && <LayoutTemplates onClose={() => setTemplatesOpen(false)} />}
437:     {launch === 'compare' && <CompareLauncher onClose={() => setLaunch(undefined)} onCreated={openSession} />}
438:     {menu && <PopoverMenu label={menu.label} at={menu.at} sections={menu.sections} onClose={() => setMenu(undefined)} />}
439:     {launch && launch !== 'compare' && prompts && <RunLauncher prompts={prompts} runs={runs ?? []} initial={launch} onClose={() => setLaunch(undefined)} onStarted={started} />}
440:   </main>;
441: }
